package net.civeira.phylax.feature.access.userpersonalapikey.application.usecase.update;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.access.userpersonalapikey.domain.UserPersonalApiKeyChangeSet;
import net.civeira.phylax.feature.identity.user.domain.UserReference;

class UserPersonalApiKeyUpdateInputUnitTest {

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the user personal api key input values are kept when converted to a change set and back")
  void test_user_personal_api_key_update_input_change_set_round_trip() {
    UserPersonalApiKeyUpdateInput input = UserPersonalApiKeyUpdateInput.builder().uid("one")
        .user(UserReference.of("one")).name("one").scopes("one")
        .lastUsedAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .expiresAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .createdAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .enabled(true).version(1).build();
    UserPersonalApiKeyChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    UserPersonalApiKeyUpdateInput copy = UserPersonalApiKeyUpdateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getUser().isPresent(), "user must be assigned by the builder");
    Assertions.assertEquals(input.getUser(), copy.getUser(),
        "user must survive the change set round trip");
    Assertions.assertTrue(input.getName().isPresent(), "name must be assigned by the builder");
    Assertions.assertEquals(input.getName(), copy.getName(),
        "name must survive the change set round trip");
    Assertions.assertTrue(input.getScopes().isPresent(), "scopes must be assigned by the builder");
    Assertions.assertEquals(input.getScopes(), copy.getScopes(),
        "scopes must survive the change set round trip");
    Assertions.assertTrue(input.getLastUsedAt().isPresent(),
        "lastUsedAt must be assigned by the builder");
    Assertions.assertEquals(input.getLastUsedAt(), copy.getLastUsedAt(),
        "lastUsedAt must survive the change set round trip");
    Assertions.assertTrue(input.getExpiresAt().isPresent(),
        "expiresAt must be assigned by the builder");
    Assertions.assertEquals(input.getExpiresAt(), copy.getExpiresAt(),
        "expiresAt must survive the change set round trip");
    Assertions.assertTrue(input.getCreatedAt().isPresent(),
        "createdAt must be assigned by the builder");
    Assertions.assertEquals(input.getCreatedAt(), copy.getCreatedAt(),
        "createdAt must survive the change set round trip");
    Assertions.assertTrue(input.getEnabled().isPresent(),
        "enabled must be assigned by the builder");
    Assertions.assertEquals(input.getEnabled(), copy.getEnabled(),
        "enabled must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the user personal api key input builder can generate a new identifier")
  void test_user_personal_api_key_update_input_new_uid() {
    UserPersonalApiKeyUpdateInput input = UserPersonalApiKeyUpdateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        UserPersonalApiKeyUpdateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the user personal api key input starts empty and the setters assign values")
  void test_user_personal_api_key_update_input_setters() {
    UserPersonalApiKeyUpdateInput empty = UserPersonalApiKeyUpdateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getUser().isEmpty(), "user must be empty by default");
    Assertions.assertSame(empty, empty.setUser(UserReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUser().isPresent(), "user must be assigned by the setter");
    Assertions.assertTrue(empty.getName().isEmpty(), "name must be empty by default");
    Assertions.assertSame(empty, empty.setName("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getName().isPresent(), "name must be assigned by the setter");
    Assertions.assertTrue(empty.getScopes().isEmpty(), "scopes must be empty by default");
    Assertions.assertSame(empty, empty.setScopes("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getScopes().isPresent(), "scopes must be assigned by the setter");
    Assertions.assertTrue(empty.getLastUsedAt().isEmpty(), "lastUsedAt must be empty by default");
    Assertions.assertSame(
        empty, empty.setLastUsedAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getLastUsedAt().isPresent(),
        "lastUsedAt must be assigned by the setter");
    Assertions.assertTrue(empty.getExpiresAt().isEmpty(), "expiresAt must be empty by default");
    Assertions.assertSame(
        empty, empty.setExpiresAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getExpiresAt().isPresent(),
        "expiresAt must be assigned by the setter");
    Assertions.assertTrue(empty.getCreatedAt().isEmpty(), "createdAt must be empty by default");
    Assertions.assertSame(
        empty, empty.setCreatedAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getCreatedAt().isPresent(),
        "createdAt must be assigned by the setter");
    Assertions.assertTrue(empty.getEnabled().isEmpty(), "enabled must be empty by default");
    Assertions.assertSame(empty, empty.setEnabled(true), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getEnabled().isPresent(), "enabled must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
